//! Tiny replacement providing the subset of the `terminal_size` API that is
//! needed for wrapping help output: query the window size of the first of
//! stdout / stderr / stdin that is attached to a terminal.

#[derive(Debug, Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Debug, Copy, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

#[cfg(unix)]
mod imp {
    use super::{Height, Width};

    #[repr(C)]
    #[derive(Default)]
    struct WinSize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }

    extern "C" {
        fn isatty(fd: i32) -> i32;
        fn ioctl(fd: i32, request: std::os::raw::c_ulong, ...) -> i32;
    }

    #[cfg(any(target_os = "linux", target_os = "android"))]
    const TIOCGWINSZ: std::os::raw::c_ulong = 0x5413;
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    const TIOCGWINSZ: std::os::raw::c_ulong = 0x40087468;

    pub fn size_of_fd(fd: i32) -> Option<(Width, Height)> {
        unsafe {
            if isatty(fd) != 1 {
                return None;
            }
            let mut ws = WinSize::default();
            if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) != 0 {
                return None;
            }
            if ws.ws_row > 0 && ws.ws_col > 0 {
                Some((Width(ws.ws_col), Height(ws.ws_row)))
            } else {
                None
            }
        }
    }

    pub fn terminal_size() -> Option<(Width, Height)> {
        size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
    }
}

#[cfg(not(unix))]
mod imp {
    use super::{Height, Width};
    pub fn terminal_size() -> Option<(Width, Height)> {
        None
    }
}

/// Returns the size of the terminal attached to stdout, stderr or stdin
/// (checked in that order), or `None` if none of them is a terminal.
pub fn terminal_size() -> Option<(Width, Height)> {
    imp::terminal_size()
}
EOF
