cd /workspace && cat > src/toml.rs <<'EOF'
//! A small, strict TOML 1.0 parser.
//!
//! Only parsing into a generic value tree is provided; the configuration
//! layer decides which keys are meaningful.

use std::fmt;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Table),
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    entries: Vec<(String, Value)>,
    meta: TableMeta,
}

#[derive(Debug, Clone, Copy, PartialEq, Default)]
struct TableMeta {
    /// Defined by a `[header]`.
    explicit: bool,
    /// Created through a dotted key (`a.b = 1`).
    dotted: bool,
    /// Written as an inline table and therefore sealed.
    inline: bool,
}

/// Kind of a table-valued array, used to keep track of `[[array]]`
/// definitions versus static arrays.
#[derive(Debug, Clone, Copy, PartialEq)]
enum ArrayKind {
    Static,
    Tables,
}

impl Table {
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn iter(&self) -> impl Iterator<Item = (&String, &Value)> {
        self.entries.iter().map(|(k, v)| (k, v))
    }

    fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.entries
            .iter_mut()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }

    fn contains(&self, key: &str) -> bool {
        self.entries.iter().any(|(k, _)| k == key)
    }

    fn insert(&mut self, key: String, value: Value) {
        self.entries.push((key, value));
    }
}

#[derive(Debug, Clone)]
pub struct ParseError {
    pub msg: String,
    pub pos: usize,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} at byte {}", self.msg, self.pos)
    }
}

type PResult<T> = Result<T, ParseError>;

pub fn parse(input: &str) -> PResult<Table> {
    let mut p = Parser {
        src: input.as_bytes(),
        text: input,
        pos: 0,
        array_kinds: Vec::new(),
    };
    p.document()
}

struct Parser<'a> {
    src: &'a [u8],
    text: &'a str,
    pos: usize,
    /// Paths of arrays created via `[[...]]` headers (their kind).
    array_kinds: Vec<(Vec<String>, ArrayKind)>,
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

impl<'a> Parser<'a> {
    fn err<T>(&self, msg: &str) -> PResult<T> {
        Err(ParseError {
            msg: msg.to_string(),
            pos: self.pos,
        })
    }

    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.src.get(self.pos + off).copied()
    }

    fn starts_with(&self, s: &str) -> bool {
        self.src[self.pos..].starts_with(s.as_bytes())
    }

    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn expect(&mut self, c: u8) -> PResult<()> {
        if self.eat(c) {
            Ok(())
        } else {
            self.err(&format!("expected `{}`", c as char))
        }
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    /// Current char (UTF-8 decoded) at the position.
    fn cur_char(&self) -> Option<char> {
        self.text[self.pos..].chars().next()
    }

    fn comment(&mut self) -> PResult<()> {
        if self.peek() != Some(b'#') {
            return Ok(());
        }
        self.pos += 1;
        while let Some(c) = self.cur_char() {
            if c == '\n' {
                break;
            }
            if c == '\r' {
                if self.peek_at(1) == Some(b'\n') {
                    break;
                }
                return self.err("bare carriage return in comment");
            }
            if (c < ' ' && c != '\t') || c == '\u{7f}' {
                return self.err("control character in comment");
            }
            self.pos += c.len_utf8();
        }
        Ok(())
    }

    /// Consumes a newline (LF or CRLF). Returns true if one was consumed.
    fn newline(&mut self) -> PResult<bool> {
        match self.peek() {
            Some(b'\n') => {
                self.pos += 1;
                Ok(true)
            }
            Some(b'\r') => {
                if self.peek_at(1) == Some(b'\n') {
                    self.pos += 2;
                    Ok(true)
                } else {
                    self.err("bare carriage return")
                }
            }
            _ => Ok(false),
        }
    }

    /// After an expression: optional whitespace, comment, then newline or EOF.
    fn line_end(&mut self) -> PResult<()> {
        self.skip_ws();
        self.comment()?;
        if self.peek().is_none() {
            return Ok(());
        }
        if self.newline()? {
            Ok(())
        } else {
            self.err("expected newline")
        }
    }

    fn document(&mut self) -> PResult<Table> {
        let mut root = Table::default();
        // Optional byte order mark.
        if self.starts_with("\u{feff}") {
            self.pos += 3;
        }
        let mut current: Vec<String> = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None => break,
                Some(b'#') => {
                    self.comment()?;
                    if self.peek().is_some() && !self.newline()? {
                        return self.err("expected newline");
                    }
                }
                Some(b'\n') | Some(b'\r') => {
                    self.newline()?;
                }
                Some(b'[') => {
                    if self.peek_at(1) == Some(b'[') {
                        self.pos += 2;
                        self.skip_ws();
                        let key = self.key()?;
                        self.skip_ws();
                        if !self.starts_with("]]") {
                            return self.err("expected `]]`");
                        }
                        self.pos += 2;
                        self.line_end()?;
                        self.define_array_table(&mut root, &key)?;
                        current = key;
                    } else {
                        self.pos += 1;
                        self.skip_ws();
                        let key = self.key()?;
                        self.skip_ws();
                        self.expect(b']')?;
                        self.line_end()?;
                        self.define_table(&mut root, &key)?;
                        current = key;
                    }
                }
                Some(_) => {
                    let key = self.key()?;
                    self.skip_ws();
                    self.expect(b'=')?;
                    self.skip_ws();
                    let value = self.value()?;
                    self.line_end()?;
                    let pos = self.pos;
                    let table = self.navigate_current(&mut root, &current, pos)?;
                    Self::insert_dotted(table, &key, value, pos)?;
                }
            }
        }
        Ok(root)
    }

    fn key(&mut self) -> PResult<Vec<String>> {
        let mut parts = Vec::new();
        loop {
            self.skip_ws();
            let part = match self.peek() {
                Some(b'"') => {
                    if self.starts_with("\"\"\"") {
                        return self.err("multi-line strings are not allowed as keys");
                    }
                    self.basic_string()?
                }
                Some(b'\'') => {
                    if self.starts_with("'''") {
                        return self.err("multi-line strings are not allowed as keys");
                    }
                    self.literal_string()?
                }
                Some(c) if is_bare_key_char(c) => {
                    let start = self.pos;
                    while let Some(c) = self.peek() {
                        if is_bare_key_char(c) {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    self.text[start..self.pos].to_string()
                }
                _ => return self.err("invalid key"),
            };
            parts.push(part);
            self.skip_ws();
            if self.peek() == Some(b'.') {
                self.pos += 1;
            } else {
                break;
            }
        }
        Ok(parts)
    }

    fn navigate_current<'t>(
        &self,
        root: &'t mut Table,
        path: &[String],
        pos: usize,
    ) -> PResult<&'t mut Table> {
        let mut table = root;
        for part in path {
            let v = match table.get_mut(part) {
                Some(v) => v,
                None => {
                    return Err(ParseError {
                        msg: "internal: missing table".into(),
                        pos,
                    })
                }
            };
            table = match v {
                Value::Table(t) => t,
                Value::Array(a) => match a.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => {
                        return Err(ParseError {
                            msg: "internal: bad array".into(),
                            pos,
                        })
                    }
                },
                _ => {
                    return Err(ParseError {
                        msg: "internal: not a table".into(),
                        pos,
                    })
                }
            };
        }
        Ok(table)
    }

    fn insert_dotted(table: &mut Table, key: &[String], value: Value, pos: usize) -> PResult<()> {
        let mut t = table;
        for part in &key[..key.len() - 1] {
            if !t.contains(part) {
                let mut nt = Table::default();
                nt.meta.dotted = true;
                t.insert(part.clone(), Value::Table(nt));
            }
            t = match t.get_mut(part) {
                Some(Value::Table(nt)) => {
                    if nt.meta.inline || nt.meta.explicit || !nt.meta.dotted {
                        return Err(ParseError {
                            msg: "cannot extend table with dotted key".into(),
                            pos,
                        });
                    }
                    nt
                }
                _ => {
                    return Err(ParseError {
                        msg: "duplicate key".into(),
                        pos,
                    })
                }
            };
        }
        let last = &key[key.len() - 1];
        if t.contains(last) {
            return Err(ParseError {
                msg: "duplicate key".into(),
                pos,
            });
        }
        t.insert(last.clone(), value);
        Ok(())
    }

    fn array_kind(&self, path: &[String]) -> Option<ArrayKind> {
        self.array_kinds
            .iter()
            .rev()
            .find(|(p, _)| p.as_slice() == path)
            .map(|(_, k)| *k)
    }

    /// Walks the intermediate tables of a header, creating implicit tables
    /// as needed.
    fn walk_header<'t>(
        &self,
        root: &'t mut Table,
        key: &[String],
    ) -> PResult<&'t mut Table> {
        let mut t = root;
        let mut path: Vec<String> = Vec::new();
        for part in key {
            path.push(part.clone());
            if !t.contains(part) {
                t.insert(part.clone(), Value::Table(Table::default()));
            }
            let is_array_table = self.array_kind(&path) == Some(ArrayKind::Tables);
            t = match t.get_mut(part) {
                Some(Value::Table(nt)) => {
                    if nt.meta.inline {
                        return self.err("cannot extend inline table");
                    }
                    nt
                }
                Some(Value::Array(a)) => {
                    if !is_array_table {
                        return self.err("cannot extend static array");
                    }
                    match a.last_mut() {
                        Some(Value::Table(nt)) => nt,
                        _ => return self.err("cannot extend array"),
                    }
                }
                _ => return self.err("key is not a table"),
            };
        }
        Ok(t)
    }

    fn define_table(&mut self, root: &mut Table, key: &[String]) -> PResult<()> {
        let (parents, last) = key.split_at(key.len() - 1);
        let last = &last[0];
        let mut full = parents.to_vec();
        full.push(last.clone());
        let is_array_table = self.array_kind(&full) == Some(ArrayKind::Tables);
        let pos = self.pos;
        let parent = self.walk_header(root, parents)?;
        match parent.get_mut(last) {
            None => {
                let mut nt = Table::default();
                nt.meta.explicit = true;
                parent.insert(last.clone(), Value::Table(nt));
                Ok(())
            }
            Some(Value::Table(t)) => {
                if t.meta.explicit || t.meta.dotted || t.meta.inline {
                    return Err(ParseError {
                        msg: "duplicate table".into(),
                        pos,
                    });
                }
                t.meta.explicit = true;
                Ok(())
            }
            Some(Value::Array(_)) if is_array_table => Err(ParseError {
                msg: "duplicate table (array of tables)".into(),
                pos,
            }),
            Some(_) => Err(ParseError {
                msg: "duplicate key".into(),
                pos,
            }),
        }
    }

    fn define_array_table(&mut self, root: &mut Table, key: &[String]) -> PResult<()> {
        let (parents, last) = key.split_at(key.len() - 1);
        let last = &last[0];
        let mut full = parents.to_vec();
        full.push(last.clone());
        let kind = self.array_kind(&full);
        let pos = self.pos;
        let parent = self.walk_header(root, parents)?;
        let mut nt = Table::default();
        nt.meta.explicit = true;
        let mut new_array = false;
        match parent.get_mut(last) {
            None => {
                parent.insert(last.clone(), Value::Array(vec![Value::Table(nt)]));
                new_array = true;
            }
            Some(Value::Array(a)) if kind == Some(ArrayKind::Tables) => {
                a.push(Value::Table(nt));
            }
            Some(_) => {
                return Err(ParseError {
                    msg: "cannot redefine as array of tables".into(),
                    pos,
                })
            }
        }
        if new_array {
            // A fresh array resets the kinds recorded for any sub paths
            // (they belong to a previous element of an enclosing array).
            self.array_kinds
                .retain(|(p, _)| !(p.len() > full.len() && p.starts_with(&full)));
            self.array_kinds.push((full, ArrayKind::Tables));
        } else {
            self.array_kinds
                .retain(|(p, _)| !(p.len() > full.len() && p.starts_with(&full)));
        }
        Ok(())
    }

    // ----------------------------------------------------------------- values

    fn value(&mut self) -> PResult<Value> {
        match self.peek() {
            None => self.err("expected value"),
            Some(b'"') => {
                if self.starts_with("\"\"\"") {
                    Ok(Value::String(self.ml_basic_string()?))
                } else {
                    Ok(Value::String(self.basic_string()?))
                }
            }
            Some(b'\'') => {
                if self.starts_with("'''") {
                    Ok(Value::String(self.ml_literal_string()?))
                } else {
                    Ok(Value::String(self.literal_string()?))
                }
            }
            Some(b'[') => self.array(),
            Some(b'{') => self.inline_table(),
            Some(b't') => {
                if self.starts_with("true") {
                    self.pos += 4;
                    Ok(Value::Boolean(true))
                } else {
                    self.err("invalid value")
                }
            }
            Some(b'f') => {
                if self.starts_with("false") {
                    self.pos += 5;
                    Ok(Value::Boolean(false))
                } else {
                    self.err("invalid value")
                }
            }
            Some(b'i') | Some(b'n') => self.number_or_date(),
            Some(c) if c == b'+' || c == b'-' || c.is_ascii_digit() => self.number_or_date(),
            _ => self.err("invalid value"),
        }
    }

    fn basic_string(&mut self) -> PResult<String> {
        self.expect(b'"')?;
        let mut out = String::new();
        loop {
            let c = match self.cur_char() {
                None => return self.err("unterminated string"),
                Some(c) => c,
            };
            match c {
                '"' => {
                    self.pos += 1;
                    return Ok(out);
                }
                '\\' => {
                    self.pos += 1;
                    out.push(self.escape()?);
                }
                '\t' => {
                    self.pos += 1;
                    out.push(c);
                }
                c if c < ' ' || c == '\u{7f}' => return self.err("control character in string"),
                c => {
                    self.pos += c.len_utf8();
                    out.push(c);
                }
            }
        }
    }

    fn escape(&mut self) -> PResult<char> {
        let c = match self.peek() {
            None => return self.err("unterminated escape"),
            Some(c) => c,
        };
        self.pos += 1;
        match c {
            b'b' => Ok('\u{8}'),
            b't' => Ok('\t'),
            b'n' => Ok('\n'),
            b'f' => Ok('\u{c}'),
            b'r' => Ok('\r'),
            b'"' => Ok('"'),
            b'\\' => Ok('\\'),
            b'u' => self.unicode_escape(4),
            b'U' => self.unicode_escape(8),
            _ => {
                self.pos -= 1;
                self.err("invalid escape")
            }
        }
    }

    fn unicode_escape(&mut self, n: usize) -> PResult<char> {
        if self.pos + n > self.src.len() {
            return self.err("invalid unicode escape");
        }
        let digits = &self.src[self.pos..self.pos + n];
        if !digits.iter().all(|c| c.is_ascii_hexdigit()) {
            return self.err("invalid unicode escape");
        }
        let s = std::str::from_utf8(digits).unwrap();
        let v = u32::from_str_radix(s, 16).unwrap();
        match char::from_u32(v) {
            Some(c) => {
                self.pos += n;
                Ok(c)
            }
            None => self.err("invalid unicode scalar value"),
        }
    }

    fn literal_string(&mut self) -> PResult<String> {
        self.expect(b'\'')?;
        let start = self.pos;
        loop {
            let c = match self.cur_char() {
                None => return self.err("unterminated string"),
                Some(c) => c,
            };
            match c {
                '\'' => {
                    let s = self.text[start..self.pos].to_string();
                    self.pos += 1;
                    return Ok(s);
                }
                '\t' => self.pos += 1,
                c if c < ' ' || c == '\u{7f}' => return self.err("control character in string"),
                c => self.pos += c.len_utf8(),
            }
        }
    }

    fn ml_basic_string(&mut self) -> PResult<String> {
        self.pos += 3;
        // A newline immediately following the delimiter is trimmed.
        self.newline()?;
        let mut out = String::new();
        loop {
            if self.starts_with("\"\"\"") {
                // Up to two additional quotes may precede the closing delimiter.
                let mut n = 3;
                while self.peek_at(n) == Some(b'"') {
                    n += 1;
                }
                if n > 5 {
                    return self.err("too many quotes");
                }
                for _ in 0..(n - 3) {
                    out.push('"');
                }
                self.pos += n;
                return Ok(out);
            }
            let c = match self.cur_char() {
                None => return self.err("unterminated string"),
                Some(c) => c,
            };
            match c {
                '\\' => {
                    self.pos += 1;
                    // Line ending backslash?
                    let save = self.pos;
                    self.skip_ws();
                    match self.peek() {
                        Some(b'\n') | Some(b'\r') => {
                            self.newline()?;
                            loop {
                                match self.peek() {
                                    Some(b' ') | Some(b'\t') => self.pos += 1,
                                    Some(b'\n') | Some(b'\r') => {
                                        self.newline()?;
                                    }
                                    _ => break,
                                }
                            }
                        }
                        _ => {
                            self.pos = save;
                            out.push(self.escape()?);
                        }
                    }
                }
                '\n' => {
                    self.pos += 1;
                    out.push('\n');
                }
                '\r' => {
                    if self.peek_at(1) == Some(b'\n') {
                        self.pos += 2;
                        out.push_str("\r\n");
                    } else {
                        return self.err("bare carriage return");
                    }
                }
                '\t' => {
                    self.pos += 1;
                    out.push('\t');
                }
                c if c < ' ' || c == '\u{7f}' => return self.err("control character in string"),
                c => {
                    self.pos += c.len_utf8();
                    out.push(c);
                }
            }
        }
    }

    fn ml_literal_string(&mut self) -> PResult<String> {
        self.pos += 3;
        self.newline()?;
        let mut out = String::new();
        loop {
            if self.starts_with("'''") {
                let mut n = 3;
                while self.peek_at(n) == Some(b'\'') {
                    n += 1;
                }
                if n > 5 {
                    return self.err("too many quotes");
                }
                for _ in 0..(n - 3) {
                    out.push('\'');
                }
                self.pos += n;
                return Ok(out);
            }
            let c = match self.cur_char() {
                None => return self.err("unterminated string"),
                Some(c) => c,
            };
            match c {
                '\n' => {
                    self.pos += 1;
                    out.push('\n');
                }
                '\r' => {
                    if self.peek_at(1) == Some(b'\n') {
                        self.pos += 2;
                        out.push_str("\r\n");
                    } else {
                        return self.err("bare carriage return");
                    }
                }
                '\t' => {
                    self.pos += 1;
                    out.push('\t');
                }
                c if c < ' ' || c == '\u{7f}' => return self.err("control character in string"),
                c => {
                    self.pos += c.len_utf8();
                    out.push(c);
                }
            }
        }
    }

    /// Skips whitespace, newlines and comments inside arrays.
    fn ws_comment_newline(&mut self) -> PResult<()> {
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'#') => self.comment()?,
                Some(b'\n') | Some(b'\r') => {
                    self.newline()?;
                }
                _ => return Ok(()),
            }
        }
    }

    fn array(&mut self) -> PResult<Value> {
        self.expect(b'[')?;
        let mut items = Vec::new();
        loop {
            self.ws_comment_newline()?;
            if self.eat(b']') {
                return Ok(Value::Array(items));
            }
            items.push(self.value()?);
            self.ws_comment_newline()?;
            if self.eat(b',') {
                continue;
            }
            if self.eat(b']') {
                return Ok(Value::Array(items));
            }
            return self.err("expected `,` or `]`");
        }
    }

    fn inline_table(&mut self) -> PResult<Value> {
        self.expect(b'{')?;
        let mut table = Table::default();
        self.skip_ws();
        if self.eat(b'}') {
            table.meta.inline = true;
            return Ok(Value::Table(table));
        }
        loop {
            self.skip_ws();
            let key = self.key()?;
            self.skip_ws();
            self.expect(b'=')?;
            self.skip_ws();
            let value = self.value()?;
            let pos = self.pos;
            Self::insert_dotted(&mut table, &key, value, pos)?;
            self.skip_ws();
            if self.eat(b',') {
                continue;
            }
            if self.eat(b'}') {
                break;
            }
            return self.err("expected `,` or `}`");
        }
        seal(&mut table);
        Ok(Value::Table(table))
    }

    fn number_or_date(&mut self) -> PResult<Value> {
        // Grab the candidate token.
        let start = self.pos;
        let mut end = self.pos;
        while end < self.src.len() {
            let c = self.src[end];
            if c.is_ascii_alphanumeric() || matches!(c, b'+' | b'-' | b'_' | b'.' | b':') {
                end += 1;
            } else {
                break;
            }
        }
        let tok = &self.text[start..end];
        // Date-times may contain a single space between date and time.
        if is_date(tok) && end < self.src.len() && self.src[end] == b' ' {
            let mut e2 = end + 1;
            while e2 < self.src.len() {
                let c = self.src[e2];
                if c.is_ascii_alphanumeric() || matches!(c, b'+' | b'-' | b'.' | b':') {
                    e2 += 1;
                } else {
                    break;
                }
            }
            let time = &self.text[end + 1..e2];
            if time.len() >= 2 && time.as_bytes()[0].is_ascii_digit() && time.as_bytes()[1].is_ascii_digit() && time.len() > 2 && time.as_bytes()[2] == b':' {
                let full = format!("{}T{}", tok, time);
                if valid_datetime(&full) {
                    self.pos = e2;
                    return Ok(Value::Datetime(self.text[start..e2].to_string()));
                }
                return self.err("invalid datetime");
            }
        }
        if tok.is_empty() {
            return self.err("invalid value");
        }
        let looks_datetime = tok.len() >= 3
            && ((tok.as_bytes()[0].is_ascii_digit()
                && tok.len() >= 5
                && tok.as_bytes()[4] == b'-'
                && tok[..4].bytes().all(|c| c.is_ascii_digit()))
                || (tok.as_bytes()[0].is_ascii_digit()
                    && tok.as_bytes()[1].is_ascii_digit()
                    && tok.as_bytes()[2] == b':'));
        if looks_datetime {
            if valid_datetime(tok) {
                self.pos = end;
                return Ok(Value::Datetime(tok.to_string()));
            }
            return self.err("invalid datetime");
        }
        if let Some(i) = parse_integer(tok) {
            self.pos = end;
            return Ok(Value::Integer(i));
        }
        if let Some(f) = parse_float(tok) {
            self.pos = end;
            return Ok(Value::Float(f));
        }
        self.err("invalid number")
    }
}

fn seal(t: &mut Table) {
    t.meta.inline = true;
    for (_, v) in t.entries.iter_mut() {
        if let Value::Table(nt) = v {
            seal(nt);
        }
    }
}

fn digits_with_underscores(s: &str, radix: u32) -> bool {
    if s.is_empty() {
        return false;
    }
    let b = s.as_bytes();
    if b[0] == b'_' || b[b.len() - 1] == b'_' {
        return false;
    }
    let mut prev_us = false;
    for &c in b {
        if c == b'_' {
            if prev_us {
                return false;
            }
            prev_us = true;
        } else {
            if !(c as char).is_digit(radix) {
                return false;
            }
            prev_us = false;
        }
    }
    true
}

fn parse_integer(tok: &str) -> Option<i64> {
    let (radix, body, neg) = if let Some(r) = tok.strip_prefix("0x") {
        (16, r, false)
    } else if let Some(r) = tok.strip_prefix("0o") {
        (8, r, false)
    } else if let Some(r) = tok.strip_prefix("0b") {
        (2, r, false)
    } else if let Some(r) = tok.strip_prefix('+') {
        (10, r, false)
    } else if let Some(r) = tok.strip_prefix('-') {
        (10, r, true)
    } else {
        (10, tok, false)
    };
    if !digits_with_underscores(body, radix) {
        return None;
    }
    if radix == 10 && body.len() > 1 && body.starts_with('0') {
        return None;
    }
    let clean: String = body.chars().filter(|&c| c != '_').collect();
    if radix == 10 {
        let s = if neg { format!("-{}", clean) } else { clean };
        s.parse::<i64>().ok()
    } else {
        i64::from_str_radix(&clean, radix).ok()
    }
}

fn parse_float(tok: &str) -> Option<f64> {
    let (sign, body) = if let Some(r) = tok.strip_prefix('+') {
        (1.0, r)
    } else if let Some(r) = tok.strip_prefix('-') {
        (-1.0, r)
    } else {
        (1.0, tok)
    };
    if body == "inf" {
        return Some(sign * f64::INFINITY);
    }
    if body == "nan" {
        return Some(f64::NAN);
    }
    // int part
    let (mantissa, exp) = match body.find(|c| c == 'e' || c == 'E') {
        Some(i) => (&body[..i], Some(&body[i + 1..])),
        None => (body, None),
    };
    let (int_part, frac) = match mantissa.find('.') {
        Some(i) => (&mantissa[..i], Some(&mantissa[i + 1..])),
        None => (mantissa, None),
    };
    if frac.is_none() && exp.is_none() {
        return None;
    }
    if !digits_with_underscores(int_part, 10) {
        return None;
    }
    if int_part.len() > 1 && int_part.starts_with('0') {
        return None;
    }
    if let Some(f) = frac {
        if !digits_with_underscores(f, 10) {
            return None;
        }
    }
    if let Some(e) = exp {
        let e = e.strip_prefix('+').or_else(|| e.strip_prefix('-')).unwrap_or(e);
        if !digits_with_underscores(e, 10) {
            return None;
        }
    }
    let clean: String = body.chars().filter(|&c| c != '_').collect();
    clean.parse::<f64>().ok().map(|v| sign * v)
}

fn is_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    valid_date(s)
}

fn num(s: &str) -> Option<u32> {
    if s.is_empty() || !s.bytes().all(|c| c.is_ascii_digit()) {
        return None;
    }
    s.parse().ok()
}

fn valid_date(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() != 10 || b[4] != b'-' || b[7] != b'-' {
        return false;
    }
    let (y, m, d) = match (num(&s[0..4]), num(&s[5..7]), num(&s[8..10])) {
        (Some(y), Some(m), Some(d)) => (y, m, d),
        _ => return false,
    };
    if !(1..=12).contains(&m) {
        return false;
    }
    let leap = (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
    let dim = match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        _ => {
            if leap {
                29
            } else {
                28
            }
        }
    };
    d >= 1 && d <= dim
}

fn valid_time(s: &str) -> bool {
    let b = s.as_bytes();
    if b.len() < 8 || b[2] != b':' || b[5] != b':' {
        return false;
    }
    let (h, m, sec) = match (num(&s[0..2]), num(&s[3..5]), num(&s[6..8])) {
        (Some(h), Some(m), Some(sec)) => (h, m, sec),
        _ => return false,
    };
    if h > 23 || m > 59 || sec > 60 {
        return false;
    }
    let rest = &s[8..];
    if rest.is_empty() {
        return true;
    }
    if let Some(frac) = rest.strip_prefix('.') {
        return !frac.is_empty() && frac.bytes().all(|c| c.is_ascii_digit());
    }
    false
}

fn valid_offset(s: &str) -> bool {
    if s == "Z" || s == "z" {
        return true;
    }
    let b = s.as_bytes();
    if b.len() != 6 || !(b[0] == b'+' || b[0] == b'-') || b[3] != b':' {
        return false;
    }
    match (num(&s[1..3]), num(&s[4..6])) {
        (Some(h), Some(m)) => h <= 23 && m <= 59,
        _ => false,
    }
}

fn valid_datetime(s: &str) -> bool {
    // Local time only.
    if s.len() >= 3 && s.as_bytes()[2] == b':' {
        return valid_time(s);
    }
    if s.len() < 10 || !valid_date(&s[..10]) {
        return false;
    }
    let rest = &s[10..];
    if rest.is_empty() {
        return true;
    }
    let rest = match rest.as_bytes()[0] {
        b'T' | b't' => &rest[1..],
        _ => return false,
    };
    // Split off the offset.
    let off_pos = rest
        .char_indices()
        .skip(8)
        .find(|&(_, c)| c == 'Z' || c == 'z' || c == '+' || c == '-')
        .map(|(i, _)| i);
    match off_pos {
        Some(i) => valid_time(&rest[..i]) && valid_offset(&rest[i..]),
        None => valid_time(rest),
    }
}
