//! Panic reporting.
//!
//! A few malformed inputs make the tool abort with a panic.  The report is
//! printed by a custom hook which mirrors the standard report layout and
//! uses the source location registered for the operation that is running.

use std::cell::Cell;
use std::io::Write;

thread_local! {
    static LOCATION: Cell<&'static str> = const { Cell::new("src/main.rs:1:1") };
}

pub const PARSE_SUBJECT: &str =
    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clog-0.11.0/src/clog.rs:607:30";
pub const MD_SHORT_HASH: &str =
    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clog-0.11.0/src/fmt/md_writer.rs:102:32";
pub const LINK_SHORT_HASH: &str =
    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clog-0.11.0/src/link_style.rs:87:18";

/// Runs `f` with `loc` registered as the location reported should it panic.
pub fn at<T>(loc: &'static str, f: impl FnOnce() -> T) -> T {
    let prev = LOCATION.with(|l| l.replace(loc));
    let r = f();
    LOCATION.with(|l| l.set(prev));
    r
}

pub fn install_hook() {
    std::panic::set_hook(Box::new(|info| {
        let msg = match info.payload_as_str() {
            Some(m) => m.to_string(),
            None => "Box<dyn Any>".to_string(),
        };
        let loc = LOCATION.with(|l| l.get());
        let name = std::thread::current()
