//! Errors reported to the user.

use std::fmt;
use std::io;

#[derive(Debug)]
pub enum Error {
    ConfigParse,
    SemVer,
    CurrentDir,
    Io,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Error::ConfigParse => "Failed to parse TOML configuration file",
            Error::SemVer => {
                "Failed to parse version into valid SemVer. Ensure the version is in the X.Y.Z format."
            }
            Error::CurrentDir => "cannot get current directory",
            Error::Io => "fatal I/O error with output file",
        };
        f.write_str(s)
    }
}

impl From<io::Error> for Error {
    fn from(_: io::Error) -> Self {
        Error::Io
    }
}

pub type Result<T> = std::result::Result<T, Error>;
