/// Location of the repository the commands are run against.
#[derive(Debug, Clone, Default)]
pub struct Repo {
    pub git_dir: Option<PathBuf>,
    pub work_tree: Option<PathBuf>,
}

impl Repo {
    fn git_dir_arg(&self) -> String {
        match &self.git_dir {
            Some(d) => format!("--git-dir={}", d.display()),
            None => String::new(),
        }
    }

    fn work_tree_arg(&self) -> String {
        match &self.work_tree {
            Some(d) => format!("--work-tree={}", d.display()),
            None => String::new(),
        }
    }

    fn run(&self, args: &[&str]) -> io::Result<String> {
        let out = Command::new("git")
            .arg(self.git_dir_arg())
            .arg(self.work_tree_arg())
            .args(args)
            .output()?;
        Ok(String::from_utf8_lossy(&out.stdout).into_owned())
    }

    /// Hash of the most recently tagged commit.
    pub fn latest_tag(&self) -> io::Result<String> {
        let out = self.run(&["rev-list", "--tags", "--max-count=1"])?;
        Ok(out.trim_matches('\n').to_string())
    }

    /// Name of the most recent tag (raw `git describe` output).
    pub fn latest_tag_version(&self) -> io::Result<String> {
        self.run(&["describe", "--tags", "--abbrev=0"])
    }

    /// Raw log output for the given revision range.
    pub fn log(&self, range: &str) -> io::Result<String> {
        let grep = format!("--grep={}", GREP_PATTERN);
        self.run(&[
            "log",
            "-E",
            &grep,
            "--format=%H%n%s%n%b%n==END==",
            range,
        ])
    }
}
