//! Parsing of raw commit records into changelog entries.

use std::sync::OnceLock;

use regex::Regex;

use crate::panic_loc;

#[derive(Debug, Clone)]
pub struct Commit {
    pub hash: String,
    pub subject: String,
    pub component: String,
    pub closes: Vec<String>,
    pub breaks: Vec<String>,
    pub commit_type: String,
}

struct Patterns {
    subject: Regex,
    closes: Regex,
    breaks: Regex,
    breaking: Regex,
}

fn patterns() -> &'static Patterns {
    static P: OnceLock<Patterns> = OnceLock::new();
    P.get_or_init(|| Patterns {
        subject: Regex::new(r"^([^:\(]+?)(?:\(([^\)]*?)?\))?:(.*)").unwrap(),
        closes: Regex::new(r"(?:Closes|Fixes|Resolves)\s((?:#(\d+)(?:,\s)?)+)").unwrap(),
        breaks: Regex::new(r"(?:Breaks|Broke)\s((?:#(\d+)(?:,\s)?)+)").unwrap(),
        breaking: Regex::new(r"(?i:breaking)").unwrap(),
    })
}

/// Maps commit type aliases to section titles.
pub struct Sections<'a> {
    pub list: &'a [(String, Vec<String>)],
}

impl<'a> Sections<'a> {
    pub fn section_for(&self, alias: &str) -> Option<&'a String> {
        self.list
            .iter()
            .find(|(_, aliases)| aliases.iter().any(|a| a == alias))
            .map(|(title, _)| title)
    }
}

/// Parses one record of `git log` output. Records whose type does not map
/// to any section yield `None`.
pub fn parse_raw_commit(raw: &str, sections: &Sections) -> Option<Commit> {
    let p = patterns();
    let mut lines = raw.lines();
    let hash = lines.next().unwrap_or("").to_string();

    let (subject, component, commit_type) =
        match lines.next().and_then(|l| p.subject.captures(l)) {
            Some(caps) => {
                let ty = caps.get(1).map(|m| m.as_str()).unwrap_or("");
                let commit_type = sections.section_for(ty)?.clone();
                (
                    caps.get(3).map(|m| m.as_str().to_string()),
                    caps.get(2).map(|m| m.as_str().to_string()),
                    commit_type,
                )
            }
            None => (None, None, sections.section_for("unk")?.clone()),
        };

    let mut closes = Vec::new();
    let mut breaks = Vec::new();
    for line in lines {
        if let Some(caps) = p.closes.captures(line) {
            if let Some(m) = caps.get(2) {
                closes.push(m.as_str().to_string());
            }
        }
        if let Some(caps) = p.breaks.captures(line) {
            if let Some(m) = caps.get(2) {
                breaks.push(m.as_str().to_string());
            }
        } else if p.breaking.is_match(line) {
            breaks.push(String::new());
        }
    }

    let subject = panic_loc::at(panic_loc::PARSE_SUBJECT, || subject.unwrap());

    Some(Commit {
        hash,
        subject,
        component: component.unwrap_or_default(),
        closes,
        breaks,
        commit_type,
    })
}
