cat > src/writer.rs <<'EOF'
//! Markdown and JSON renderers.

use std::collections::BTreeMap;
use std::io::{self, Write};

use crate::commit::Commit;
use crate::config::LinkStyle;
use crate::date;
use crate::links;
use crate::panic_loc;

/// Commits of one section grouped by component (sorted).
pub type ComponentMap = BTreeMap<String, Vec<Commit>>;

/// Everything the renderers need to know besides the commits.
pub struct Options<'a> {
    pub version: Option<&'a str>,
    pub patch_version: bool,
    pub subtitle: Option<&'a str>,
    pub repo: Option<&'a str>,
    pub link_style: LinkStyle,
}

pub fn write_markdown<W: Write>(
    w: &mut W,
    opts: &Options,
    sections: &[(&String, &ComponentMap)],
) -> io::Result<()> {
    let version = opts.version.unwrap_or("");
    let subtitle = opts.subtitle.unwrap_or("");
    let level = if opts.patch_version { "###" } else { "##" };
    write!(
        w,
        "<a name=\"{}\"></a>\n{} {} {} ({})\n\n",
        version,
        level,
        version,
        subtitle,
        date::today()
    )?;

    for (title, components) in sections {
        write!(w, "\n#### {}\n\n", title)?;
        for (component, entries) in components.iter() {
            let nested = entries.len() > 1 && !component.is_empty();
            let prefix = if nested {
                writeln!(w, "* **{}:**", component)?;
                "  *".to_string()
            } else if !component.is_empty() {
                format!("* **{}:**", component)
            } else {
                "* ".to_string()
            };

            for entry in entries {
                let short = links::short_hash(&entry.hash, panic_loc::MD_SHORT_HASH);
                let link = links::commit_link(opts.link_style, &entry.hash, opts.repo);
                write!(w, "{} {} ([{}]({})", prefix, entry.subject, short, link)?;

                if !entry.closes.is_empty() {
                    let s = issue_list(opts, &entry.closes);
                    write!(w, ", closes {}", s)?;
                }
                if !entry.breaks.is_empty() {
                    let s = issue_list(opts, &entry.breaks);
                    // A lone "[#]()" stems from a bare BREAKING marker.
                    if s.len() != 5 {
                        write!(w, ", breaks {}", s)?;
                    }
                }
                w.write_all(b")\n")?;
            }
        }
    }
    Ok(())
}

fn issue_list(opts: &Options, issues: &[String]) -> String {
    issues
        .iter()
        .map(|i| {
            format!(
                "[#{}]({})",
                i,
                links::issue_link(opts.link_style, i, opts.repo)
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn json_issues<W: Write>(w: &mut W, opts: &Options, issues: &[String]) -> io::Result<()> {
    w.write_all(b"[")?;
    let mut it = issues.iter().peekable();
    while let Some(issue) = it.next() {
        let link = links::issue_link(opts.link_style, issue, opts.repo);
        write!(w, "{{\"issue\":{},\"issue_link\":{:?}}}", issue, link)?;
        if it.peek().is_some() {
            w.write_all(b",")?;
        }
    }
    w.write_all(b"]")
}

pub fn write_json<W: Write>(
    w: &mut W,
    opts: &Options,
    sections: &[(&String, &ComponentMap)],
