//! Generation of commit and issue links for the supported hosting styles.

use crate::config::LinkStyle;
use crate::panic_loc;

/// The first eight bytes of a commit hash.
pub fn short_hash(hash: &str, loc: &'static str) -> String {
    panic_loc::at(loc, || hash[0..8].to_string())
}

pub fn commit_link(style: LinkStyle, hash: &str, repo: Option<&str>) -> String {
    match repo {
        None => short_hash(hash, panic_loc::LINK_SHORT_HASH),
        Some(r) => match style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/commit/{}", r, hash),
            LinkStyle::Stash => format!("{}/commits/{}", r, hash),
            LinkStyle::Cgit => format!("{}/commit/?id={}", r, hash),
        },
    }
}

pub fn issue_link(style: LinkStyle, issue: &str, repo: Option<&str>) -> String {
    match repo {
        None => issue.to_string(),
        Some(r) => match style {
            LinkStyle::Github | LinkStyle::Gitlab => format!("{}/issues/{}", r, issue),
            LinkStyle::Stash | LinkStyle::Cgit => issue.to_string(),
        },
    }
}
