//! Markdown and JSON renderers.

use std::collections::BTreeMap;
use std::io::{self, Write};

use crate::commit::Commit;
use crate::config::LinkStyle;
use crate::date;
use crate::links;
use crate::panic_loc;

/// Commits of one section grouped by component (sorted).
pub type ComponentMap = BTreeMap<String, Vec<Commit>>;

/// Everything the renderers need to know besides the commits.
pub struct Options<'a> {
    pub version: Option<&'a str>,
    pub patch_version: bool,
    pub subtitle: Option<&'a str>,
    pub repo: Option<&'a str>,
    pub link_style: LinkStyle,
}

pub fn write_markdown<W: Write>(
    w: &mut W,
    opts: &Options,
    sections: &[(&String, &ComponentMap)],
) -> io::Result<()> {
    let version = opts.version.unwrap_or("");
    let subtitle = opts.subtitle.unwrap_or("");
    let level = if opts.patch_version { "###" } else { "##" };
    write!(
        w,
        "<a name=\"{}\"></a>\n{} {} {} ({})\n\n",
        version,
        level,
        version,
        subtitle,
        date::today()
    )?;

    for (title, components) in sections {
        write!(w, "\n#### {}\n\n", title)?;
        for (component, entries) in components.iter() {
            let nested = entries.len() > 1 && !component.is_empty();
            let prefix = if nested {
                writeln!(w, "* **{}:**", component)?;
                "  *".to_string()
            } else if !component.is_empty() {
                format!("* **{}:**", component)
            } else {
                "* ".to_string()
            };

            for entry in entries {
                let short = links::short_hash(&entry.hash, panic_loc::MD_SHORT_HASH);
                let link = links::commit_link(opts.link_style, &entry.hash, opts.repo);
                write!(w, "{} {} ([{}]({})", prefix, entry.subject, short, link)?;

                if !entry.closes.is_empty() {
                    let s = issue_list(opts, &entry.closes);
                    write!(w, ", closes {}", s)?;
                }
                if !entry.breaks.is_empty() {
                    let s = issue_list(opts, &entry.breaks);
                    // A lone "[#]()" stems from a bare BREAKING marker.
                    if s.len() != 5 {
                        write!(w, ", breaks {}", s)?;
                    }
                }
                w.write_all(b")\n")?;
            }
        }
    }
    Ok(())
}

fn issue_list(opts: &Options, issues: &[String]) -> String {
    issues
        .iter()
        .map(|i| {
            format!(
                "[#{}]({})",
                i,
                links::issue_link(opts.link_style, i, opts.repo)
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn json_issues<W: Write>(w: &mut W, opts: &Options, issues: &[String]) -> io::Result<()> {
    w.write_all(b"[")?;
    let mut it = issues.iter().peekable();
    while let Some(issue) = it.next() {
        let link = links::issue_link(opts.link_style, issue, opts.repo);
        write!(w, "{{\"issue\":{},\"issue_link\":{:?}}}", issue, link)?;
        if it.peek().is_some() {
            w.write_all(b",")?;
        }
    }
    w.write_all(b"]")
}

pub fn write_json<W: Write>(
    w: &mut W,
    opts: &Options,
    sections: &[(&String, &ComponentMap)],
) -> io::Result<()> {
    let version = opts.version.map(|s| s.to_string());
    let subtitle = match opts.subtitle {
        Some(s) => s.to_string(),
        None => "null".to_string(),
    };
    write!(
        w,
        "{{\"header\":{{\"version\":{:?},\"patch_version\":{},\"subtitle\":{},\"date\":\"{}\"}},\"sections\":",
        version,
        opts.patch_version,
        subtitle,
        date::today()
    )?;

    if sections.is_empty() {
        w.write_all(b"null")?;
    } else {
        w.write_all(b"[")?;
        let mut s_it = sections.iter().peekable();
        while let Some((title, components)) = s_it.next() {
            write!(w, "{{\"title\":{:?},\"commits\":[", title)?;
            let mut c_it = components.iter().peekable();
            while let Some((component, entries)) = c_it.next() {
                let mut e_it = entries.iter().peekable();
                while let Some(entry) = e_it.next() {
                    w.write_all(b"{\"component\":")?;
                    if component.is_empty() {
                        w.write_all(b"null,")?;
                    } else {
                        write!(w, "{:?},", component)?;
                    }
                    let link = links::commit_link(opts.link_style, &entry.hash, opts.repo);
                    write!(
                        w,
                        "\"subject\":{:?},\"commit_link\":{:?},\"closes\":",
                        entry.subject, link
                    )?;
                    if entry.closes.is_empty() {
                        w.write_all(b"null,")?;
                    } else {
                        json_issues(w, opts, &entry.closes)?;
                        w.write_all(b",")?;
                    }
                    w.write_all(b"\"breaks\":")?;
                    if entry.breaks.is_empty() {
                        w.write_all(b"null")?;
                    } else {
                        // The issue list written here mirrors the closed issues.
                        json_issues(w, opts, &entry.closes)?;
                    }
                    w.write_all(b"}")?;
                    if e_it.peek().is_some() {
                        w.write_all(b",")?;
                    }
                }
                if c_it.peek().is_some() {
                    w.write_all(b",")?;
                }
            }
            w.write_all(b"]}")?;
            if s_it.peek().is_some() {
                w.write_all(b",")?;
            }
        }
        w.write_all(b"]")?;
    }
    w.write_all(b"}")
}
