//! Changelog generation: gathering settings, reading commits and writing
//! the result.

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

use crate::cli::Args;
use crate::commit::{self, Commit, Sections};
use crate::config::{Config, LinkStyle, OutputFormat};
use crate::error::{Error, Result};
use crate::git::Repo;
use crate::writer::{self, ComponentMap, Options};

const CONFIG_FILE: &str = ".clog.toml";
const BREAKING_SECTION: &str = "Breaking Changes";

#[derive(Debug)]
pub struct Clog {
    pub repo_dirs: Repo,
    pub repository: Option<String>,
    pub link_style: LinkStyle,
    pub version: Option<String>,
    pub patch_version: bool,
    pub subtitle: Option<String>,
    pub from: Option<String>,
    pub to: String,
    pub format: OutputFormat,
    pub outfile: Option<String>,
    pub infile: Option<String>,
    pub sections: Vec<(String, Vec<String>)>,
}

impl Clog {
    /// Builds the settings from a configuration file, then points the git
    /// commands at the given directories.
    fn new(git_dir: PathBuf, work_tree: PathBuf, cfg_file: &Path) -> Result<Clog> {
        let cfg = Config::load(cfg_file)?;
        let mut clog = Clog {
            repo_dirs: Repo::default(),
            repository: None,
            link_style: LinkStyle::Github,
            version: None,
            patch_version: false,
            subtitle: None,
            from: None,
            to: "HEAD".to_string(),
            format: OutputFormat::Markdown,
            outfile: None,
            infile: None,
            sections: Vec::new(),
        };

        if cfg.from_latest_tag {
            clog.from = Some(clog.repo_dirs.latest_tag()?);
        }
        if let Some(r) = cfg.repository {
            clog.repository = Some(r);
        }
        if let Some(s) = cfg.subtitle {
            clog.subtitle = Some(s);
        }
        if let Some(l) = cfg.link_style {
            clog.link_style = l;
        }
        if let Some(f) = cfg.output_format {
            clog.format = f;
        }
        if let Some(o) = cfg.outfile {
            clog.outfile = Some(o);
        }
        if let Some(i) = cfg.infile {
            clog.infile = Some(i);
        }
        if let Some(c) = cfg.changelog {
            clog.infile = Some(c.clone());
            clog.outfile = Some(c);
        }
        clog.sections = cfg.sections;

        clog.repo_dirs.git_dir = Some(git_dir);
        clog.repo_dirs.work_tree = Some(work_tree);
        Ok(clog)
    }

    /// Uses `file` as configuration and assumes the repository lives next
    /// to it.
    fn from_file(file: &Path) -> Result<Clog> {
        let cfg_file = if file.is_relative() {
            let cwd = env::current_dir().map_err(|_| Error::CurrentDir)?;
            cwd.join(file)
        } else {
            file.to_path_buf()
        };
        let mut dir = cfg_file.clone();
        dir.pop();
        let git_dir = dir.join(".git");
        Clog::new(git_dir, dir, &cfg_file)
    }

    /// Uses explicit repository directories and the default configuration
    /// file of the current directory.
    fn with_dirs(git_dir: &str, work_tree: &str) -> Result<Clog> {
        let cwd = env::current_dir().map_err(|_| Error::CurrentDir)?;
        let cfg_file = cwd.join(CONFIG_FILE);
        Clog::new(PathBuf::from(git_dir), PathBuf::from(work_tree), &cfg_file)
    }

    pub fn from_args(args: &Args) -> Result<Clog> {
        let mut clog = match (&args.git_dir, &args.work_tree) {
            (Some(g), Some(w)) => Clog::with_dirs(g, w)?,
            _ => {
                let mut c = Clog::from_file(Path::new(&args.config))?;
                if let Some(g) = &args.git_dir {
                    c.repo_dirs.git_dir = Some(PathBuf::from(g));
                }
                if let Some(w) = &args.work_tree {
                    c.repo_dirs.work_tree = Some(PathBuf::from(w));
                }
                c
            }
        };

        if let Some(v) = &args.setversion {
            clog.version = Some(v.clone());
        } else if args.major || args.minor || args.patch {
            let tag = clog.repo_dirs.latest_tag_version()?;
            let had_v = tag.starts_with('v') || tag.starts_with('V');
            let bare = tag.trim_start_matches(|c| c == 'v' || c == 'V');
            let mut v = semver::Version::parse(bare).map_err(|_| Error::SemVer)?;
            if args.major {
                v.major = v.major.wrapping_add(1);
                v.minor = 0;
                v.patch = 0;
            } else if args.minor {
                v.minor = v.minor.wrapping_add(1);
                v.patch = 0;
            } else {
                v.patch = v.patch.wrapping_add(1);
                clog.patch_version = true;
            }
            clog.version = Some(format!("{}{}", if had_v { "v" } else { "" }, v));
        }

        if args.from_latest_tag {
            clog.from = Some(clog.repo_dirs.latest_tag()?);
        } else if let Some(f) = &args.from {
            clog.from = Some(f.clone());
        }

        clog.to = args.to.clone();
        clog.repository = args.repository.clone();
        clog.link_style = LinkStyle::from_name(&args.link_style).unwrap_or(LinkStyle::Github);
        clog.subtitle = args.subtitle.clone();

        if let Some(o) = &args.outfile {
            clog.outfile = Some(o.clone());
        }
        if let Some(c) = &args.changelog {
            clog.infile = Some(c.clone());
            clog.outfile = Some(c.clone());
        }
        if let Some(i) = &args.infile {
            clog.infile = Some(i.clone());
        }

        clog.format = OutputFormat::from_name(&args.format).unwrap_or(OutputFormat::Markdown);
        Ok(clog)
    }

    pub fn get_commits(&self) -> Result<Vec<Commit>> {
        let range = match &self.from {
            Some(from) => format!("{}..{}", from, self.to),
            None => "HEAD".to_string(),
        };
        let out = self.repo_dirs.log(&range)?;
        let sections = Sections {
            list: &self.sections,
        };
        Ok(out
            .split("\n==END==\n")
            .filter_map(|raw| commit::parse_raw_commit(raw, &sections))
            .filter(|c| c.commit_type != "Unknown")
            .collect())
    }

    fn section_map(&self, commits: Vec<Commit>) -> BTreeMap<String, ComponentMap> {
        let mut map: BTreeMap<String, ComponentMap> = BTreeMap::new();
        for c in commits {
            if !c.breaks.is_empty() {
                map.entry(BREAKING_SECTION.to_string())
                    .or_default()
                    .entry(c.component.clone())
                    .or_default()
                    .push(c.clone());
            }
            map.entry(c.commit_type.clone())
                .or_default()
                .entry(c.component.clone())
                .or_default()
                .push(c);
        }
        map
    }

    fn render<W: Write>(&self, w: &mut W, commits: Vec<Commit>) -> io::Result<()> {
        let map = self.section_map(commits);
        let ordered: Vec<(&String, &ComponentMap)> = self
            .sections
            .iter()
            .filter_map(|(title, _)| map.get(title).map(|m| (title, m)))
            .collect();
        let opts = Options {
            version: self.version.as_deref(),
            patch_version: self.patch_version,
            subtitle: self.subtitle.as_deref(),
            repo: self.repository.as_deref(),
            link_style: self.link_style,
        };
        match self.format {
            OutputFormat::Markdown => writer::write_markdown(w, &opts, &ordered),
            OutputFormat::Json => writer::write_json(w, &opts, &ordered),
        }
    }

    pub fn write_changelog(&self, commits: Vec<Commit>) -> Result<()> {
        if let Some(out) = &self.outfile {
            let old = read_lossless(self.infile.as_deref().unwrap_or(out));
            let mut file = fs::File::create(out)?;
            self.render(&mut file, commits)?;
            file.write_all(b"\n\n\n")?;
            file.write_all(old.as_bytes())?;
            file.flush()?;
        } else if let Some(inf) = &self.infile {
            let old = read_lossless(inf);
            let stdout = io::stdout();
            let mut w = io::BufWriter::new(stdout.lock());
            self.render(&mut w, commits)?;
            w.write_all(b"\n\n\n")?;
            w.write_all(old.as_bytes())?;
            w.flush()?;
        } else {
            let stdout = io::stdout();
            let mut w = io::BufWriter::new(stdout.lock());
            self.render(&mut w, commits)?;
            w.flush()?;
        }
        Ok(())
    }
}

/// Reads a whole text file; any failure yields an empty string.
fn read_lossless(path: &str) -> String {
    match fs::read(path) {
        Ok(bytes) => String::from_utf8(bytes).unwrap_or_default(),
        Err(_) => String::new(),
    }
}
EOF
