mod cli;
mod clog;
mod commit;
mod config;
mod date;
mod error;
mod git;
mod links;
mod panic_loc;
mod toml;
mod writer;

use std::io::Write;
use std::time::Instant;

fn run(args: &cli::Args) -> error::Result<()> {
    let clog = clog::Clog::from_args(args)?;
    let commits = clog.get_commits()?;
    clog.write_changelog(commits)?;
    Ok(())
}

fn main() {
    panic_loc::install_hook();
    let start = Instant::now();
    let args = cli::Args::parse();

    match run(&args) {
        Ok(()) => {
            println!("changelog written. (took {} ms)", start.elapsed().as_millis());
        }
        Err(e) => {
            let _ = std::io::stdout().flush();
            eprintln!("\x1b[1;31merror:\x1b[0m {}", e);
            std::process::exit(1);
        }
    }
}
