//! TOML reading.
//!
//! The parser builds a flat list of tables (one per `[header]`, plus the
//! root table) whose key/value pairs are kept in source order.  Nested
//! structure is only resolved lazily while walking the document for the
//! values that are actually needed (see [`MapWalker`]); this mirrors how the
//! configuration format has always been interpreted, including its quirks
//! (e.g. later duplicate keys win in maps, datetimes are only checked
//! lexically).

use std::collections::HashMap;

#[derive(Debug)]
pub struct Error;

pub type Result<T> = std::result::Result<T, Error>;

/// A parsed value.
#[derive(Debug, Clone)]
pub enum Val {
    Integer(i64),
    Float(f64),
    Boolean(bool),
    String(String),
    Datetime(String),
    Array(Vec<Val>),
    InlineTable(Vec<(String, Val)>),
    DottedTable(Vec<(String, Val)>),
}

// ------------------------------------------------------------------ tokens

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Whitespace(String),
    Newline,
    Comment,
    Equals,
    Period,
    Comma,
    Colon,
    Plus,
    LeftBrace,
    RightBrace,
    LeftBracket,
    RightBracket,
    Keylike(String),
    Str { val: String, multiline: bool },
}

#[derive(Clone)]
struct Tokenizer<'a> {
    input: &'a str,
    /// Byte offset of the next character.
    pos: usize,
}

fn is_keylike(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || ch == '-' || ch == '_'
}

impl<'a> Tokenizer<'a> {
    fn new(input: &'a str) -> Tokenizer<'a> {
        let mut t = Tokenizer { input, pos: 0 };
        t.eatc('\u{feff}');
        t
    }

    /// Next character, folding CRLF into LF. Returns (offset, char).
    fn one(&mut self) -> Option<(usize, char)> {
        let rest = &self.input[self.pos..];
        let mut it = rest.chars();
        let c = it.next()?;
        let start = self.pos;
        self.pos += c.len_utf8();
        if c == '\r' && self.input[self.pos..].starts_with('\n') {
            self.pos += 1;
            return Some((start, '\n'));
        }
        Some((start, c))
    }

    fn peek_char(&self) -> Option<char> {
        let mut c = self.clone();
        c.one().map(|(_, ch)| ch)
    }

    fn eatc(&mut self, ch: char) -> bool {
        let mut c = self.clone();
        match c.one() {
            Some((_, x)) if x == ch => {
                *self = c;
                true
            }
            _ => false,
        }
    }

    fn next(&mut self) -> Result<Option<Token>> {
        let (start, ch) = match self.one() {
            Some(x) => x,
            None => return Ok(None),
        };
        let tok = match ch {
            '\n' => Token::Newline,
            ' ' | '\t' => {
                while let Some(c) = self.peek_char() {
                    if c == ' ' || c == '\t' {
                        self.one();
                    } else {
                        break;
                    }
                }
                Token::Whitespace(self.input[start..self.pos].to_string())
            }
            '#' => {
                self.comment_body();
                Token::Comment
            }
            '=' => Token::Equals,
            '.' => Token::Period,
            ',' => Token::Comma,
            ':' => Token::Colon,
            '+' => Token::Plus,
            '{' => Token::LeftBrace,
            '}' => Token::RightBrace,
            '[' => Token::LeftBracket,
            ']' => Token::RightBracket,
            '\'' => return self.read_string('\'').map(Some),
            '"' => return self.read_string('"').map(Some),
            c if is_keylike(c) => {
                while let Some(c) = self.peek_char() {
                    if is_keylike(c) {
                        self.one();
                    } else {
                        break;
                    }
                }
                Token::Keylike(self.input[start..self.pos].to_string())
            }
            _ => return Err(Error),
        };
        Ok(Some(tok))
    }

    fn peek(&self) -> Result<Option<Token>> {
        self.clone().next()
    }

    fn comment_body(&mut self) {
        while let Some(ch) = self.peek_char() {
            if ch != '\t' && ch < '\u{20}' {
                break;
            }
            self.one();
        }
    }

    fn eat_whitespace(&mut self) {
        while self.eatc(' ') || self.eatc('\t') {}
    }

    fn eat(&mut self, expected: &Token) -> Result<bool> {
        match self.peek()? {
            Some(ref t) if t == expected => {
                self.next()?;
                Ok(true)
            }
            _ => Ok(false),
        }
    }

    fn expect(&mut self, expected: &Token) -> Result<()> {
        match self.next()? {
            Some(ref t) if t == expected => Ok(()),
            _ => Err(Error),
        }
    }

    fn eat_newline_or_eof(&mut self) -> Result<()> {
        match self.next()? {
            None | Some(Token::Newline) => Ok(()),
            Some(_) => Err(Error),
        }
    }

    fn eat_comment(&mut self) -> Result<bool> {
        if !self.eatc('#') {
            return Ok(false);
        }
        self.comment_body();
        self.eat_newline_or_eof().map(|()| true)
    }

    fn skip_to_newline(&mut self) {
        loop {
            match self.one() {
                Some((_, '\n')) | None => break,
                _ => {}
            }
        }
    }

    fn table_key(&mut self) -> Result<String> {
        match self.next()? {
            Some(Token::Keylike(k)) => Ok(k),
            Some(Token::Str { val, multiline }) => {
                if multiline {
                    Err(Error)
                } else {
                    Ok(val)
                }
            }
            _ => Err(Error),
        }
    }

    fn hex(&mut self, len: usize) -> Result<char> {
        let mut buf = String::with_capacity(len);
        for _ in 0..len {
            match self.one() {
                Some((_, ch)) if ch.is_ascii_hexdigit() => buf.push(ch),
                _ => return Err(Error),
            }
        }
        let v = u32::from_str_radix(&buf, 16).map_err(|_| Error)?;
        char::from_u32(v).ok_or(Error)
    }

    fn read_string(&mut self, delim: char) -> Result<Token> {
        let mut multiline = false;
        if self.eatc(delim) {
            if self.eatc(delim) {
                multiline = true;
            } else {
                return Ok(Token::Str {
                    val: String::new(),
                    multiline: false,
                });
            }
        }
        let mut val = String::new();
        let mut n = 0usize;
        loop {
            n += 1;
            match self.one() {
                Some((_, '\n')) => {
                    if multiline {
                        if n == 1 {
                            val.clear();
                        } else {
                            val.push('\n');
                        }
                        continue;
                    }
                    return Err(Error);
                }
                Some((_, ch)) if ch == delim => {
                    if multiline {
                        if !self.eatc(delim) {
                            val.push(delim);
                            continue;
                        }
                        if !self.eatc(delim) {
                            val.push(delim);
                            val.push(delim);
                            continue;
                        }
                        if self.eatc(delim) {
                            val.push(delim);
                        }
                        if self.eatc(delim) {
                            val.push(delim);
                        }
                    }
                    return Ok(Token::Str { val, multiline });
                }
                Some((_, ch)) => {
                    if delim == '"' && ch == '\\' {
                        self.escape(&mut val, multiline)?;
                    } else if ch == '\t' || (ch >= '\u{20}' && ch != '\u{7f}') {
                        val.push(ch);
                    } else {
                        return Err(Error);
                    }
                }
                None => return Err(Error),
            }
        }
    }

    fn escape(&mut self, val: &mut String, multi: bool) -> Result<()> {
        match self.one() {
            Some((_, '"')) => val.push('"'),
            Some((_, '\\')) => val.push('\\'),
            Some((_, 'b')) => val.push('\u{8}'),
            Some((_, 'f')) => val.push('\u{c}'),
            Some((_, 'n')) => val.push('\n'),
            Some((_, 'r')) => val.push('\r'),
            Some((_, 't')) => val.push('\t'),
            Some((_, 'u')) => val.push(self.hex(4)?),
            Some((_, 'U')) => val.push(self.hex(8)?),
            Some((_, c)) if multi && (c == ' ' || c == '\t' || c == '\n') => {
                if c != '\n' {
                    while let Some(ch) = self.peek_char() {
                        match ch {
                            ' ' | '\t' => {
                                self.one();
                            }
                            '\n' => {
                                self.one();
                                break;
                            }
                            _ => return Err(Error),
                        }
                    }
                }
                while let Some(ch) = self.peek_char() {
                    match ch {
                        ' ' | '\t' | '\n' => {
                            self.one();
                        }
                        _ => break,
                    }
                }
            }
            _ => return Err(Error),
        }
        Ok(())
    }
}

// ------------------------------------------------------------------ parser

#[derive(Debug)]
pub struct TableEntry {
    header: Vec<String>,
    values: Option<Vec<(String, Val)>>,
    array: bool,
}

enum Line {
    Table { header: Vec<String>, array: bool },
    KeyValue(Vec<String>, Val),
}

struct Parser<'a> {
    tokens: Tokenizer<'a>,
}

impl<'a> Parser<'a> {
    fn tables(&mut self) -> Result<Vec<TableEntry>> {
        let mut tables = Vec::new();
        let mut cur = TableEntry {
            header: Vec::new(),
            values: None,
            array: false,
        };
        while let Some(line) = self.line()? {
            match line {
                Line::Table { header, array } => {
                    if !cur.header.is_empty() || cur.values.is_some() {
                        tables.push(cur);
                    }
                    cur = TableEntry {
                        header,
                        values: Some(Vec::new()),
                        array,
                    };
                }
                Line::KeyValue(key, value) => {
                    let values = cur.values.get_or_insert_with(Vec::new);
                    add_dotted_key(key, value, values)?;
                }
            }
        }
        if !cur.header.is_empty() || cur.values.is_some() {
            tables.push(cur);
        }
        Ok(tables)
    }

    fn line(&mut self) -> Result<Option<Line>> {
        loop {
            self.tokens.eat_whitespace();
            if self.tokens.eat_comment()? {
                continue;
            }
            if self.tokens.eat(&Token::Newline)? {
                continue;
            }
            break;
        }
        match self.tokens.peek()? {
            Some(Token::LeftBracket) => self.table_header().map(Some),
            Some(_) => self.key_value().map(Some),
            None => Ok(None),
        }
    }

    fn table_header(&mut self) -> Result<Line> {
        self.tokens.expect(&Token::LeftBracket)?;
        let array = self.tokens.eat(&Token::LeftBracket)?;
        let mut h = self.tokens.clone();
        self.tokens.skip_to_newline();

        let mut header = Vec::new();
        let mut first = true;
        loop {
            h.eat_whitespace();
            if first || h.eat(&Token::Period)? {
                first = false;
                h.eat_whitespace();
                header.push(h.table_key()?);
            } else {
                h.expect(&Token::RightBracket)?;
                if array {
                    h.expect(&Token::RightBracket)?;
                }
                h.eat_whitespace();
                if !h.eat_comment()? {
                    h.eat_newline_or_eof()?;
                }
                break;
            }
        }
        Ok(Line::Table { header, array })
    }

    fn key_value(&mut self) -> Result<Line> {
        let key = self.dotted_key()?;
        self.tokens.eat_whitespace();
        self.tokens.expect(&Token::Equals)?;
        self.tokens.eat_whitespace();
        let value = self.value()?;
        self.tokens.eat_whitespace();
        if !self.tokens.eat_comment()? {
            self.tokens.eat_newline_or_eof()?;
        }
        Ok(Line::KeyValue(key, value))
    }

    fn dotted_key(&mut self) -> Result<Vec<String>> {
        let mut result = vec![self.tokens.table_key()?];
        self.tokens.eat_whitespace();
        while self.tokens.eat(&Token::Period)? {
            self.tokens.eat_whitespace();
            result.push(self.tokens.table_key()?);
            self.tokens.eat_whitespace();
        }
        Ok(result)
    }

    fn value(&mut self) -> Result<Val> {
        match self.tokens.next()? {
            Some(Token::Str { val, .. }) => Ok(Val::String(val)),
            Some(Token::Keylike(k)) if k == "true" => Ok(Val::Boolean(true)),
            Some(Token::Keylike(k)) if k == "false" => Ok(Val::Boolean(false)),
            Some(Token::Keylike(k)) => self.parse_keylike(&k),
            Some(Token::Plus) => self.number_leading_plus(),
            Some(Token::LeftBrace) => self.inline_table().map(Val::InlineTable),
            Some(Token::LeftBracket) => self.array().map(Val::Array),
            _ => Err(Error),
        }
    }

    fn parse_keylike(&mut self, key: &str) -> Result<Val> {
        if key == "inf" || key == "nan" {
            return self.number_or_date(key);
        }
        match key.chars().next() {
            Some('-') | Some('0'..='9') => self.number_or_date(key),
            _ => Err(Error),
        }
    }

    fn number_or_date(&mut self, s: &str) -> Result<Val> {
        if s.contains('T')
            || s.contains('t')
            || (s.len() > 1 && s[1..].contains('-') && !s.contains("e-") && !s.contains("E-"))
        {
            self.datetime(s, false).map(Val::Datetime)
        } else if self.tokens.eat(&Token::Colon)? {
            self.datetime(s, true).map(Val::Datetime)
        } else {
            self.number(s)
        }
    }

    fn expect_keylike(&mut self) -> Result<String> {
        match self.tokens.next()? {
            Some(Token::Keylike(k)) => Ok(k),
            _ => Err(Error),
        }
    }

    fn datetime(&mut self, date: &str, colon_eaten: bool) -> Result<String> {
        let mut out = date.to_string();
        let mut look = self.tokens.clone();
        if let Ok(Some(Token::Whitespace(ws))) = look.next() {
            if ws == " " {
                if let Ok(Some(Token::Keylike(hour))) = look.next() {
                    self.tokens.next()?;
                    self.tokens.next()?;
                    out.push(' ');
                    out.push_str(&hour);
                }
            }
        }
        if colon_eaten || self.tokens.eat(&Token::Colon)? {
            out.push(':');
            out.push_str(&self.expect_keylike()?);
            self.tokens.expect(&Token::Colon)?;
            out.push(':');
            out.push_str(&self.expect_keylike()?);
            if self.tokens.eat(&Token::Period)? {
                out.push('.');
                out.push_str(&self.expect_keylike()?);
            }
            if self.tokens.eat(&Token::Plus)? {
                out.push('+');
                out.push_str(&self.expect_keylike()?);
            }
            if self.tokens.eat(&Token::Colon)? {
                out.push(':');
                out.push_str(&self.expect_keylike()?);
            }
        }
        Ok(out)
    }

    fn number(&mut self, s: &str) -> Result<Val> {
        if let Some(r) = s.strip_prefix("0x") {
            integer(r, 16).map(Val::Integer)
        } else if let Some(r) = s.strip_prefix("0o") {
            integer(r, 8).map(Val::Integer)
        } else if let Some(r) = s.strip_prefix("0b") {
            integer(r, 2).map(Val::Integer)
        } else if s.contains('e') || s.contains('E') {
            self.float(s, None).map(Val::Float)
        } else if self.tokens.eat(&Token::Period)? {
            let after = self.expect_keylike()?;
            self.float(s, Some(&after)).map(Val::Float)
        } else if s == "inf" {
            Ok(Val::Float(f64::INFINITY))
        } else if s == "-inf" {
            Ok(Val::Float(f64::NEG_INFINITY))
        } else if s == "nan" {
            Ok(Val::Float(f64::NAN))
        } else if s == "-nan" {
            Ok(Val::Float(-f64::NAN))
        } else {
            integer(s, 10).map(Val::Integer)
        }
    }

    fn number_leading_plus(&mut self) -> Result<Val> {
        let s = self.expect_keylike()?;
        self.number(&s)
    }

    fn float(&mut self, s: &str, after_decimal: Option<&str>) -> Result<f64> {
        let (integral, mut suffix) = parse_integer(s, true, false, 10)?;
        let mut fraction = None;
        let after_owned;
        if let Some(after) = after_decimal {
            if !suffix.is_empty() {
                return Err(Error);
            }
            after_owned = after.to_string();
            let (a, b) = parse_integer(&after_owned, false, true, 10)?;
            fraction = Some(a.to_string());
            suffix = b;
        }
        let mut exponent = None;
        if suffix.starts_with('e') || suffix.starts_with('E') {
            let (a, b) = if suffix.len() == 1 {
                self.tokens.eat(&Token::Plus)?;
                let k = self.expect_keylike()?;
                let (a, b) = parse_integer(&k, false, true, 10)?;
                (a.to_string(), b.to_string())
            } else {
                let (a, b) = parse_integer(&suffix[1..], true, true, 10)?;
                (a.to_string(), b.to_string())
            };
            if !b.is_empty() {
                return Err(Error);
            }
            exponent = Some(a);
        } else if !suffix.is_empty() {
            return Err(Error);
        }

        let mut number: String = integral
            .trim_start_matches('+')
            .chars()
            .filter(|c| *c != '_')
            .collect();
        if let Some(f) = fraction {
            number.push('.');
            number.extend(f.chars().filter(|c| *c != '_'));
        }
        if let Some(e) = exponent {
            number.push('E');
            number.extend(e.chars().filter(|c| *c != '_'));
        }
        match number.parse::<f64>() {
            Ok(n) if n.is_finite() => Ok(n),
            _ => Err(Error),
        }
    }

    fn inline_table(&mut self) -> Result<Vec<(String, Val)>> {
        let mut ret = Vec::new();
        self.tokens.eat_whitespace();
        if self.tokens.eat(&Token::RightBrace)? {
            return Ok(ret);
        }
        loop {
            let key = self.dotted_key()?;
            self.tokens.eat_whitespace();
            self.tokens.expect(&Token::Equals)?;
            self.tokens.eat_whitespace();
            let value = self.value()?;
            add_dotted_key(key, value, &mut ret)?;
            self.tokens.eat_whitespace();
            if self.tokens.eat(&Token::RightBrace)? {
                return Ok(ret);
            }
            self.tokens.expect(&Token::Comma)?;
            self.tokens.eat_whitespace();
        }
    }

    fn intermediate(&mut self) -> Result<()> {
        loop {
            self.tokens.eat_whitespace();
            if !self.tokens.eat(&Token::Newline)? && !self.tokens.eat_comment()? {
                break;
            }
        }
        Ok(())
    }

    fn array(&mut self) -> Result<Vec<Val>> {
        let mut ret = Vec::new();
        loop {
            self.intermediate()?;
            if self.tokens.eat(&Token::RightBracket)? {
                return Ok(ret);
            }
            ret.push(self.value()?);
            self.intermediate()?;
            if !self.tokens.eat(&Token::Comma)? {
                break;
            }
        }
        self.intermediate()?;
        self.tokens.expect(&Token::RightBracket)?;
        Ok(ret)
    }
}

fn add_dotted_key(mut parts: Vec<String>, value: Val, values: &mut Vec<(String, Val)>) -> Result<()> {
    let key = parts.remove(0);
    if parts.is_empty() {
        values.push((key, value));
        return Ok(());
    }
    if let Some(pos) = values.iter().position(|(k, _)| *k == key) {
        return match &mut values[pos].1 {
            Val::DottedTable(v) => add_dotted_key(parts, value, v),
            _ => Err(Error),
        };
    }
    values.push((key, Val::DottedTable(Vec::new())));
    let last = values.len() - 1;
    if let Val::DottedTable(v) = &mut values[last].1 {
        add_dotted_key(parts, value, v)?;
    }
    Ok(())
}

fn parse_integer(s: &str, allow_sign: bool, allow_leading_zeros: bool, radix: u32) -> Result<(&str, &str)> {
    let mut first = true;
    let mut first_zero = false;
    let mut underscore = false;
    let mut end = s.len();
    for (i, c) in s.char_indices() {
        if i == 0 && (c == '+' || c == '-') && allow_sign {
            continue;
        }
        if c == '0' && first {
            first_zero = true;
        } else if c.is_digit(radix) {
            if !first && first_zero && !allow_leading_zeros {
                return Err(Error);
            }
            underscore = false;
        } else if c == '_' && first {
            return Err(Error);
        } else if c == '_' && !underscore {
            underscore = true;
        } else {
            end = i;
            break;
        }
        first = false;
    }
    if first || underscore {
        return Err(Error);
    }
    Ok((&s[..end], &s[end..]))
}

fn integer(s: &str, radix: u32) -> Result<i64> {
    let (prefix, suffix) = parse_integer(s, radix == 10, radix != 10, radix)?;
    if !suffix.is_empty() {
        return Err(Error);
    }
    let clean = prefix.replace('_', "");
    i64::from_str_radix(clean.trim_start_matches('+'), radix).map_err(|_| Error)
}

// ------------------------------------------------------------- tree walking

/// The parsed document: a flat list of tables plus lookup indices.
pub struct Document {
    tables: Vec<TableEntry>,
    /// Tables indexed by their full header.
    indices: HashMap<Vec<String>, Vec<usize>>,
    /// Tables indexed by every prefix of their header.
    pindices: HashMap<Vec<String>, Vec<usize>>,
}

pub fn parse(input: &str) -> Result<Document> {
    let mut p = Parser {
        tokens: Tokenizer::new(input),
    };
    let tables = p.tables()?;
    let mut indices: HashMap<Vec<String>, Vec<usize>> = HashMap::new();
    let mut pindices: HashMap<Vec<String>, Vec<usize>> = HashMap::new();
    for (i, t) in tables.iter().enumerate() {
        indices.entry(t.header.clone()).or_default().push(i);
        for len in 0..=t.header.len() {
            pindices.entry(t.header[..len].to_vec()).or_default().push(i);
        }
    }
    Ok(Document {
        tables,
        indices,
        pindices,
    })
}

impl Document {
    /// Walker over the top level of the document.
    pub fn root(&self) -> MapWalker {
        MapWalker {
            values: Vec::new(),
            next_value: None,
            depth: 0,
            cur: 0,
            cur_parent: 0,
            max: self.tables.len(),
            array: false,
        }
    }
}

/// Something that can be read as a value.
pub enum Node {
    Value(Val),
    Tables(MapWalker),
}

/// Iterates over the entries of a (possibly header-defined) table.
pub struct MapWalker {
    values: Vec<(String, Val)>,
    next_value: Option<Val>,
    depth: usize,
    cur: usize,
    cur_parent: usize,
    max: usize,
    pub array: bool,
}

fn first_from(entries: &[usize], from: usize) -> usize {
    match entries.binary_search(&from) {
        Ok(i) | Err(i) => i,
    }
}

impl MapWalker {
    pub fn next_key(&mut self, doc: &mut Document) -> Result<Option<String>> {
        if self.cur_parent == self.max || self.cur == self.max {
            return Ok(None);
        }
        loop {
            if !self.values.is_empty() {
                let (k, v) = self.values.remove(0);
                self.next_value = Some(v);
                return Ok(Some(k));
            }

            let prefix: Vec<String> = doc.tables[self.cur_parent].header[..self.depth].to_vec();
            let next_table = doc.pindices.get(&prefix).and_then(|entries| {
                let start = first_from(entries, self.cur);
                if start == entries.len() || entries[start] < self.cur {
                    return None;
                }
                entries[start..]
                    .iter()
                    .copied()
                    .filter(|&i| i < self.max)
                    .find(|&i| doc.tables[i].values.is_some())
            });

            let pos = match next_table {
                Some(p) => p,
                None => return Ok(None),
            };
            self.cur = pos;

            if self.cur_parent != pos {
                if doc.tables[self.cur_parent].header == doc.tables[pos].header {
                    // Table defined twice.
                    return Err(Error);
                }
                let parent_len = doc.tables[self.cur_parent].header.len();
                let cur_len = doc.tables[pos].header.len();
                if cur_len < parent_len {
                    self.cur_parent = pos;
                }
            }

            let table = &mut doc.tables[pos];
            if self.depth != table.header.len() {
                return Ok(Some(table.header[self.depth].clone()));
            }
            if table.array {
                return Err(Error);
            }
            self.values = table.values.take().unwrap_or_default();
        }
    }

    pub fn next_value(&mut self, doc: &mut Document) -> Node {
        if let Some(v) = self.next_value.take() {
            return Node::Value(v);
        }
        let t = &doc.tables[self.cur];
        let array = t.array && self.depth + 1 == t.header.len();
        self.cur += 1;
        Node::Tables(MapWalker {
            values: Vec::new(),
            next_value: None,
            depth: self.depth + if array { 0 } else { 1 },
            cur_parent: self.cur - 1,
            cur: 0,
            max: self.max,
            array,
        })
    }

    /// For array-of-tables walkers: the next element.
    pub fn next_element(&mut self, doc: &mut Document) -> Option<MapWalker> {
        if self.cur_parent == self.max {
            return None;
        }
        let header = doc.tables[self.cur_parent].header.clone();
        let start_idx = self.cur_parent + 1;
        let next = doc
            .indices
            .get(&header)
            .and_then(|entries| {
                let start = first_from(entries, start_idx);
                if start == entries.len() || entries[start] < start_idx {
                    return None;
                }
                entries[start..]
                    .iter()
                    .copied()
                    .filter(|&i| i < self.max)
                    .find(|&i| doc.tables[i].array)
            })
            .unwrap_or(self.max);
        let values = doc.tables[self.cur_parent].values.take().unwrap_or_default();
        let child = MapWalker {
            values,
            next_value: None,
            depth: self.depth + 1,
            cur_parent: self.cur_parent,
            max: next,
            cur: 0,
            array: false,
        };
        // The caller fully consumes `child` before asking for the next one.
        self.pending_parent = next;
        Some(child)
    }
}
